import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address owner = address(0x1);
    function setUp() public {
        vm.prank(owner);
        c = new C();
    }
    function testFuzz_property(address target, uint256 value, uint256 extraDeposit) public {
