        (bool ok,) = address(c).call{value: extraDeposit}("");
        require(ok, "deposit failed");
        // Now use sendMoney as the driver entry point
        vm.prank(owner);
        c.sendMoney(target, value);
        // After the call, balance may be reduced or unchanged; the invariant is that withdrawAll as owner does not revert
        vm.prank(owner);
        bool withdrawSucceeded = true;
        try c.withdrawAll() {
            withdrawSucceeded = true;
        } catch {
            withdrawSucceeded = false;
        }
        assertTrue(withdrawSucceeded);
    }
}

