pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount) public {
        vm.assume(depositAmount > 0);
        vm.assume(depositAmount <= address(c).balance.max - address(c).balance);
        vm.deal(address(c), depositAmount);
        (bool ok,) = address(c).call{value: depositAmount}("");
        vm.assume(ok);

        address owner = c.owner();
        uint256 ownerBalanceBefore = owner.balance;
        uint256 contractBalanceBefore = address(c).balance;
        vm.prank(owner);
        c.withdrawAll();
        uint256 ownerBalanceAfter = owner.balance;

        assertTrue(ownerBalanceAfter - ownerBalanceBefore == contractBalanceBefore);
    }
}

