contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 _value) public {
        // 1. Keep the value within admissible bounds (non-zero and not exceeding some sent amount)
        vm.assume(_value > 0);
        vm.assume(_value <= 100 ether);
        // Fund the contract with enough ether
        vm.deal(address(c), 100 ether);
        // 2. Record balance before withdraw, then call withdraw as owner
        uint256 balBefore = address(c).balance;
        vm.prank(c.owner());
        c.withdraw(_value);
        uint256 balAfter = address(c).balance;
        // 3. The balance must decrease by _value (reference holds, bug breaks because balance stays same)
        assertTrue(balAfter == balBefore - _value);
    }
